 lit_th:"最 = 'ที่สุด' 中 = 'กลาง' รวมกันคือ 'ตรงกลางที่สุด' นึกภาพกำลังทำอะไรอยู่เต็มที่ แล้วมีบางอย่างแทรกเข้ามา",
